#pragma once

// 3D preview tables for the Inventory tab, generated by tools/build_model_catalog.py
// from a real CS2 install (pak01_dir.vpk + scripts/items/items_game.txt). Do not edit.
//
// Both tables are indexed exactly like the catalogue they shadow, so a slot or a skin row
// can look its geometry up directly. A null Finish means "nothing to put on the model":
// the item is not a weapon finish at all.
namespace nl::models {

// A weapon finish. Most resolve to a material, which names its own texture slots; the
// newest ones have no material and are described by loose maps instead.
struct Finish {
    const char* material; // .vmat of the finish, or nullptr
    const char* color;    // loose maps, used when material is null
    const char* normal;
    const char* roughness;
    const char* ao;
    const char* mask;     // where the finish covers the base weapon
    int style;            // paint kit style; 5 and 6 are palette paints
    bool palette;         // the colour texture indexes g_vColor0..3 rather than being it
};

extern const char* const weapon_model[]; // indexed like nl::inv::weapons
extern const int weapon_model_count;
extern const Finish item_finish[];       // indexed like nl::inv::items
extern const int item_finish_count;

// World model of a catalogue weapon, or nullptr when it has no 3D preview.
const char* weapon(int weapon_index);
// Finish of a catalogue item, or nullptr when it has none.
const Finish* finish(int item_index);

} // namespace nl::models
